#!/usr/bin/env python3
# Probe A: sharpness of InducedSimpleLowestAlcove on symmetric powers S^n(V) = H^0((n,0,..,0)) of GL_N over Fbar_p.
# Weight spaces of S^n(V) are 1-dim (monomials), so a G-submodule is a span of monomials closed under the divided-power
# root operators E_ij^(k): x^a -> C(a_j,k) x^(a + k e_i - k e_j) (Dist(G) is generated by these and the torus).
# S^n(V) is simple iff the monomial graph with edges for C(a_j,k) != 0 mod p is strongly connected. Exact integer arithmetic.
import itertools, sys
from math import comb
def monos(N, n):
    if N == 1: yield (n,); return
    for a in range(n + 1):
        for r in monos(N - 1, n - a): yield (a,) + r
def simple(N, n, p):
    ms = list(monos(N, n)); idx = {m: i for i, m in enumerate(ms)}
    adj = [[] for _ in ms]
    for m in ms:
        for i in range(N):
            for j in range(N):
                if i == j: continue
                for k in range(1, m[j] + 1):
                    if comb(m[j], k) % p:
                        t = list(m); t[i] += k; t[j] -= k; adj[idx[m]].append(idx[tuple(t)])
    def reach(s):
        seen = {s}; st = [s]
        while st:
            v = st.pop()
            for w in adj[v]:
                if w not in seen: seen.add(w); st.append(w)
        return seen
    full = len(ms)
    return all(len(reach(s)) == full for s in range(full)), full
bad = 0; rows = []
for p in (2, 3, 5, 7):
    for N in (2, 3, 4):
        for n in range(0, 2 * p + 1):
            if comb(n + N - 1, N - 1) > 400: continue
            cond = n + (N - 1) <= p  # lam_1 - lam_N + (N-1) <= p (the binding pair i=1, j=N)
            s, dim = simple(N, n, p)
            if cond and not s: bad += 1
            rows.append((p, N, n, dim, cond, s))
for p, N, n, dim, cond, s in rows:
    tag = 'IN-ALCOVE' if cond else 'outside'
    print(f"p={p} GL{N} n={n} dim={dim} {tag} simple={s}")
print("counterexamples to 'condition => simple':", bad)
print("GL2 n=p simple?", [(p, simple(2, p, p)[0]) for p in (2, 3, 5, 7)])
print("outside alcove but simple (condition not necessary):", sum(1 for r in rows if not r[4] and r[5]))
